from collections import OrderedDict

class TTLCache:
    def __init__(self, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.typed = typed
        self.cache = OrderedDict()
        self.expiry = OrderedDict()

    def __call__(self, func):
        def wrapper(*args, **kwargs):
            key = self._make_key(args, kwargs)
            current_time = self.timer()
            if key in self.cache:
                if current_time < self.expiry[key]:
                    return self.cache[key]
                else:
                    self.cache.pop(key)
                    self.expiry.pop(key)
            if len(self.cache) >= self.maxsize:
                self.cache.popitem(last=False)
                self.expiry.popitem(last=False)
            result = func(*args, **kwargs)
            self.cache[key] = result
            self.expiry[key] = current_time + self.ttl
            return result
        return wrapper

    def _make_key(self, args, kwargs):
        key = args
        if kwargs:
            sorted_items = sorted(kwargs.items())
            key += (sorted_items,)
        if self.typed:
            key += tuple(type(arg) for arg in args)
            if kwargs:
                key += tuple(type(value) for _, value in sorted_items)
        return key

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    return TTLCache(maxsize, ttl, timer, typed)
