import functools

def cachedmethod(cache, key=hash, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                with lock:
                    return cache.get(key(args, kwargs), default=lambda: cache.set(key(args, kwargs), func(self, *args, **kwargs)))
            else:
                return cache.get(key(args, kwargs), default=lambda: cache.set(key(args, kwargs), func(self, *args, **kwargs)))
        return wrapper
    return decorator
