            if self.in_style == 'named' and self.out_style == 'named':
                return sql, params
            elif self.in_style == 'named' and self.out_style == 'ordinal':
                out_params = []
                for key in params:
                    out_params.append(params[key])
                return sql, out_params
        elif isinstance(params, Sequence):
            if self.in_style == 'ordinal' and self.out_style == 'named':
                out_params = {}
                for i, value in enumerate(params):
                    out_params[f':p{i+1}'] = value
                return sql, out_params
            elif self.in_style == 'ordinal' and self.out_style == 'ordinal':
                return sql, params
        raise ValueError("Unsupported parameter style conversion")
