from typing import Any, AnyStr, Dict, Iterable, List, Sequence, Tuple, Union

class SQLParams:
    in_style = None

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_params = []
    formatted_sql = sql

    for params in many_params:
        if isinstance(params, dict):
            if self.SQLParams.in_style == 'named':
                out_param = {}
                for key, value in params.items():
                    out_param[key] = value
                out_params.append(out_param)
            else:
                raise ValueError("In-style parameters must be a sequence if in_style is not named.")
        elif isinstance(params, Sequence):
            if self.SQLParams.in_style == 'ordinal':
                out_param = list(params)
                out_params.append(out_param)
            else:
                raise ValueError("In-style parameters must be a mapping if in_style is not ordinal.")
        else:
            raise ValueError("In-style parameters must be a mapping or a sequence.")

    return formatted_sql, out_params
