            type_value = inventory.get('type')
            if type_value:
                version_match = re.match(r'^v(\d+\.\d+\.\d+)$', type_value)
                if version_match:
                    self.spec_version = version_match.group(1)

        # Example validation logic based on spec_version
        if self.spec_version == '1.0.0':
            if 'items' not in inventory:
                raise ValueError("Inventory must contain 'items' key for version 1.0.0")
            if not isinstance(inventory['items'], list):
                raise ValueError("Inventory 'items' must be a list for version 1.0.0")
        elif self.spec_version == '2.0.0':
            if 'products' not in inventory:
                raise ValueError("Inventory must contain 'products' key for version 2.0.0")
            if not isinstance(inventory['products'], list):
                raise ValueError("Inventory 'products' must be a list for version 2.0.0")
        else:
            raise ValueError(f"Unsupported specification version: {self.spec_version}")
