                    content_digest = self.calculate_content_digest(item)
                    content_digests[item] = content_digest

        self.validate_content_digests(content_digests)

    def load_inventory(self, inventory_name):
        inventory_path = f"{inventory_name}_inventory.txt"
        with open(inventory_path, 'r') as file:
            inventory = {}
            for line in file:
                key, value = line.strip().split(':')
                inventory[key] = value
        return inventory

    def calculate_content_digest(self, item_path):
        with open(item_path, 'rb') as file:
            content = file.read()
            return hashlib.sha256(content).hexdigest()

    def validate_content_digests(self, content_digests):
        for item, digest in content_digests.items():
            calculated_digest = self.calculate_content_digest(item)
            if calculated_digest != digest:
                raise ValueError(f"Content digest mismatch for {item}: expected {digest}, got {calculated_digest}")
